begin;
set local lock_timeout='5s';
set local statement_timeout='120s';

-- COMP-011: new version only. Historic response_json and queued native payloads
-- remain untouched/unversioned; v17 page-21 citation is not locally available.
create table public.custodial_completion_taxonomy_versions (
 version text primary key,
 catalog_text text not null,
 catalog_json jsonb not null,
 catalog_sha256 text not null check (catalog_sha256 ~ '^[0-9a-f]{64}$'),
 source_note text not null,
 created_at timestamptz not null default statement_timestamp(),
 check (catalog_json=catalog_text::jsonb),
 check (catalog_json->>'version'=version)
);
alter table public.custodial_completion_taxonomy_versions enable row level security;
alter table public.custodial_completion_taxonomy_versions force row level security;
revoke all on public.custodial_completion_taxonomy_versions from public,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;

create function public.custodial_completion_taxonomy_immutable()
returns trigger language plpgsql set search_path=pg_catalog,public as $fn$
begin
 raise exception using errcode='55000',message='completion taxonomy versions are immutable';
end $fn$;
revoke all on function public.custodial_completion_taxonomy_immutable() from public,anon,authenticated,service_role,custodial_application_reader;
create trigger custodial_completion_taxonomy_immutable before update or delete on public.custodial_completion_taxonomy_versions
 for each row execute function public.custodial_completion_taxonomy_immutable();
alter table public.custodial_completion_taxonomy_versions enable always trigger custodial_completion_taxonomy_immutable;

insert into public.custodial_completion_taxonomy_versions(version,catalog_text,catalog_json,catalog_sha256,source_note)
