create function public.custodial_completion_assert_taxonomy(p_response jsonb)
returns void language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare t jsonb; v_catalog jsonb; v_digest text; v_area text;
 v_raw jsonb; v_selections jsonb; v_item jsonb; v_label text; v_id text; i integer; v_kind text;
begin
 if not (p_response ? 'taxonomy') then return; end if;
 t:=p_response->'taxonomy';
 if jsonb_typeof(t) is distinct from 'object'
   or jsonb_typeof(t->'version') is distinct from 'string'
   or jsonb_typeof(t->'digest') is distinct from 'string' then
  raise exception using errcode='22023',message='completion taxonomy metadata is malformed';
 end if;
 select c.catalog_json,c.catalog_sha256 into v_catalog,v_digest
 from public.custodial_completion_taxonomy_versions c where c.version=t->>'version';
 if not found or t->>'digest' is distinct from v_digest then
  raise exception using errcode='22023',message='completion taxonomy version or digest is unavailable';
 end if;
 v_area:=p_response->>'form_type';
 if v_area not in ('restroom','exhibit') or v_catalog->'areas'->v_area is null then
  raise exception using errcode='22023',message='completion taxonomy area is invalid';
 end if;
 for v_kind in select unnest(array['services','issues']::text[]) loop
  v_raw:=p_response->(case when v_kind='services' then 'services_performed' else 'maintenance_issues_found' end);
  v_selections:=t->v_kind;
  if jsonb_typeof(v_raw) is distinct from 'array' or jsonb_typeof(v_selections) is distinct from 'array'
    or jsonb_array_length(v_raw)<>jsonb_array_length(v_selections) then
   raise exception using errcode='22023',message='completion taxonomy selections do not match raw answers';
  end if;
  for i in 0..jsonb_array_length(v_raw)-1 loop
   v_item:=v_selections->i;
   if jsonb_typeof(v_raw->i) is distinct from 'string' or jsonb_typeof(v_item) is distinct from 'object'
    or jsonb_typeof(v_item->'id') is distinct from 'string'
    or jsonb_typeof(v_item->'label') is distinct from 'string' then
    raise exception using errcode='22023',message='completion taxonomy selection is malformed';
   end if;
   v_label:=v_raw->>i; v_id:=v_item->>'id';
   if v_item->>'label' is distinct from v_label or btrim(v_label)='' then
    raise exception using errcode='22023',message='completion taxonomy selection changed the original answer';
   end if;
   if v_kind='services' and v_id='OTHER' then
    if exists(select 1 from jsonb_array_elements(v_catalog->'areas'->v_area->v_kind) known
      where known->>'label'=v_label) then
     raise exception using errcode='22023',message='known completion service cannot be classified OTHER';
    end if;
   elsif not exists(select 1 from jsonb_array_elements(v_catalog->'areas'->v_area->v_kind) known
      where known->>'id'=v_id and known->>'label'=v_label) then
    raise exception using errcode='22023',message='completion taxonomy selection is not in this version';
   end if;
  end loop;
 end loop;
end $fn$;
revoke all on function public.custodial_completion_assert_taxonomy(jsonb) from public,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;

create function public.custodial_completion_taxonomy_response_guard()
returns trigger language plpgsql set search_path=pg_catalog,public as $fn$
begin
 perform public.custodial_completion_assert_taxonomy(new.response_json);
 return new;
end $fn$;
revoke all on function public.custodial_completion_taxonomy_response_guard() from public,anon,authenticated,service_role,custodial_application_reader;
create trigger custodial_completion_taxonomy_response_guard before insert or update of response_json
 on public.completion_responses for each row execute function public.custodial_completion_taxonomy_response_guard();
alter table public.completion_responses enable always trigger custodial_completion_taxonomy_response_guard;

-- A server-only catalog lookup is the source/copy contract for the employee
-- form; absence of metadata on a historic response never implies this version.
create function public.custodial_completion_taxonomy_read(p_version text default 'COMP011-20261003-v1')
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare v_result jsonb;
begin
 select jsonb_build_object('version',c.version,'digest',c.catalog_sha256,'catalog',c.catalog_json,
  'source_note',c.source_note) into v_result
 from public.custodial_completion_taxonomy_versions c where c.version=p_version;
 if v_result is null then raise exception using errcode='P0002',message='completion taxonomy version not found'; end if;
 return v_result;
end $fn$;
revoke all on function public.custodial_completion_taxonomy_read(text) from public,anon,authenticated,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;
grant execute on function public.custodial_completion_taxonomy_read(text) to service_role;

-- Exact-session manager evidence, preserving original response and source
-- provenance; this is not an inspection result or an area-wide issue summary.
create function public.custodial_manager_completion_evidence(
 p_manager_id uuid,p_session_uuid text,p_backend_execution_secret text
) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare s public.sessions%rowtype; r public.completion_responses%rowtype;
 v_catalog jsonb; v_digest text; v_native boolean:=false;
 v_issue boolean; v_issue_known boolean:=false; v_work text; v_class text; v_raw_issue_count integer:=0;
 v_open integer:=0; v_work_order integer:=0; v_fixed integer:=0; v_legacy_closed integer:=0; v_total integer:=0;
 v_tickets jsonb:='[]'::jsonb; v_follow_up text;
begin
 perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
 if p_manager_id is null or p_session_uuid is null or length(p_session_uuid)=0 or length(p_session_uuid)>128
   or not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id
    and m.active=true and m.revoked_at is null and m.is_system_principal=false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]) then
  raise exception using errcode='42501',message='active named manager authority is required';
 end if;
 select * into s from public.sessions where session_uuid=p_session_uuid;
 if not found then raise exception using errcode='P0002',message='cleaning session was not found'; end if;
 select * into r from public.completion_responses where session_id=s.id;
 if not found then
  return jsonb_build_object('session_id',s.id,'session_uuid',s.session_uuid,
   'location_id',s.location_id,'employee_id',s.employee_id,'device_id',s.device_id,
   'started_at',s.started_at,'ended_at',s.ended_at,
   'session_status',s.status,'completion_recorded',false,'classification','no_completion_record',
   'inspection_evaluation','not_performed_by_this_reader');
 end if;
 select c.catalog_json,c.catalog_sha256 into v_catalog,v_digest from public.custodial_completion_taxonomy_versions c
  where c.version=r.response_json#>>'{taxonomy,version}';
 select exists(
  select 1 from public.custodial_offline_reconciliation_records receipt
  join public.custodial_offline_actor_contexts context on context.context_id=receipt.context_id
  where receipt.completion_response_id=r.id and receipt.session_id=s.id
   and receipt.state='committed' and context.status='committed' and s.status='closed'
   and receipt.occurrence_id=context.occurrence_id and receipt.occurrence_fingerprint=context.occurrence_fingerprint
   and receipt.credential_id=context.credential_id and receipt.location_id=s.location_id
   and context.location_id=s.location_id and r.location_id=s.location_id
   and context.client_session_id=s.client_session_id and receipt.client_session_id=s.client_session_id
   and receipt.client_completion_id=r.client_completion_id and receipt.original_employee_id=s.employee_id
   and context.employee_id=s.employee_id and receipt.device_id=s.device_id and context.device_id=s.device_id
   and r.device_id=s.device_id and r.submitted_by_employee_id=s.employee_id
   and receipt.payload_json->'response_json'=r.response_json
   and context.native_start_attestation_version='custodial-native-start.v1'
   and context.native_scan_entry_id is not null
   and context.native_completion_attestation_version='custodial-native-completion.v2'
   and context.native_completion_attestation_sha256 ~ '^[0-9a-f]{64}$'
   and context.native_finish_scan_entry_id is not null
   and context.native_finish_scan_entry_id<>context.native_scan_entry_id
   and context.started_at=s.started_at and context.native_completed_at=s.ended_at
   and context.native_completed_at>context.started_at and context.native_completed_at<=statement_timestamp()
   and exists(select 1 from public.custodial_offline_scan_event_evidence evidence
    where evidence.context_id=context.context_id and evidence.reconciliation_id=receipt.reconciliation_id
      and evidence.session_id=s.id and lower(evidence.client_event_id)=context.native_finish_scan_entry_id::text
      and evidence.event_payload->>'event_type'='scan_finish'
      and evidence.event_payload->>'result'='ok'
      and evidence.event_payload#>>'{payload_json,entry_source}'='native-nfc'
      and evidence.event_payload->>'scanned_at'=public.custodial_canonical_utc_millis(context.native_completed_at))
 ) into v_native;
 select count(*),count(*) filter(where t.status='open'),
  count(*) filter(where t.resolution_outcome='work_order_sent'),
  count(*) filter(where t.resolution_outcome='mark_fixed'),
  count(*) filter(where t.status='closed' and t.resolution_outcome is null),
  coalesce(jsonb_agg(jsonb_build_object('ticket_id',t.id,'status',t.status,
   'resolution_outcome',t.resolution_outcome,'external_work_order_reference',t.external_work_order_reference,
   'resolution_actor_manager_id',t.resolution_actor_manager_id,'closed_at',t.closed_at,
   'issue_summary',t.issue_summary) order by t.reported_at,t.id) filter(where t.id is not null),'[]'::jsonb)
 into v_total,v_open,v_work_order,v_fixed,v_legacy_closed,v_tickets
 from public.maintenance_tickets t where t.completion_response_id=r.id and t.issue_source='completion_form';
 if jsonb_typeof(r.response_json->'attention_needed')='boolean' then
  v_issue_known:=true; v_issue:=(r.response_json->>'attention_needed')::boolean;
 end if;
 if jsonb_typeof(r.response_json->'maintenance_issues_found')='array' then
  v_raw_issue_count:=jsonb_array_length(r.response_json->'maintenance_issues_found');
 end if;
 if v_raw_issue_count=0 and (lower(coalesce(r.response_json->>'out_of_order_signed','')) in ('yes','true')
    or nullif(btrim(coalesce(r.response_json->>'out_of_order_details','')),'') is not null) then
  v_raw_issue_count:=1;
 end if;
 if v_total>0 or v_raw_issue_count>0
    or lower(coalesce(r.response_json->>'out_of_order_signed','')) in ('yes','true')
    or nullif(btrim(coalesce(r.response_json->>'out_of_order_details','')),'') is not null then
  v_issue_known:=true; v_issue:=true;
 end if;
 v_work:=r.response_json->>'work_result';
 if not v_issue_known then v_follow_up:='unknown';
 elsif not v_issue then v_follow_up:='none_reported';
 elsif v_total>0 and v_fixed=v_total and v_raw_issue_count>0 and v_total>=v_raw_issue_count
  then v_follow_up:='linked_tickets_marked_fixed_coverage_unverified';
 else v_follow_up:='required_or_unresolved';
 end if;
 if not v_native then v_class:='historical_or_unverified_completion';
 elsif v_work='checked_no_cleaning_needed' then v_class:='checked_only';
 elsif v_work not in ('full','details') or v_work is null then v_class:='unknown';
 elsif v_follow_up='none_reported' then v_class:='cleaned_no_issues_reported';
 elsif v_follow_up='linked_tickets_marked_fixed_coverage_unverified'
  then v_class:='cleaned_linked_tickets_marked_fixed_coverage_unverified';
 elsif v_follow_up='required_or_unresolved' then v_class:='cleaned_follow_up_required';
 else v_class:='cleaned_issue_state_unknown';
 end if;
 return jsonb_build_object('session_id',s.id,'session_uuid',s.session_uuid,'session_status',s.status,
  'location_id',s.location_id,'employee_id',s.employee_id,'device_id',s.device_id,
  'started_at',s.started_at,'ended_at',s.ended_at,
  'completion_recorded',true,'completion_response_id',r.id,'client_completion_id',r.client_completion_id,
  'submitted_at',r.submitted_at,'original_response',r.response_json,
  'taxonomy_version',r.response_json#>>'{taxonomy,version}',
  'taxonomy_digest',r.response_json#>>'{taxonomy,digest}',
  'taxonomy_status',case when not (r.response_json ? 'taxonomy') then 'unversioned_historical_or_protected_draft'
   when v_catalog is null or v_digest is distinct from r.response_json#>>'{taxonomy,digest}' then 'metadata_unverified_legacy'
   else 'versioned_current_catalog' end,
  'catalog_digest',v_digest,'catalog',v_catalog,
  'native_exact_receipt_admitted',v_native,'work_result',v_work,'issue_reported',case when v_issue_known then to_jsonb(v_issue) else 'null'::jsonb end,
  'linked_completion_tickets',v_tickets,'linked_ticket_count',v_total,'linked_open_count',v_open,
  'linked_work_order_sent_count',v_work_order,'linked_mark_fixed_count',v_fixed,
  'linked_legacy_closed_unknown_count',v_legacy_closed,'raw_reported_issue_count',v_raw_issue_count,
  'linked_issue_count_shortfall',greatest(v_raw_issue_count-v_total,0),'follow_up',v_follow_up,
  'classification',v_class,'inspection_evaluation','not_performed_by_this_reader');
end $fn$;
revoke all on function public.custodial_manager_completion_evidence(uuid,text,text) from public,anon,authenticated,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;
grant execute on function public.custodial_manager_completion_evidence(uuid,text,text) to service_role;

-- Restore is pinned to the exact new private catalog, reader/guard definitions,
-- trigger states, and explicit denied/direct RPC grants. No historical row is
-- rewritten; the single catalog seed remains source-controlled above.
lock table public.custodial_release_authority_restore_inventory in share row exclusive mode;
alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
do $recovery$ declare obj record;next_order integer;changed integer;begin
 for obj in with funcs as (
  select p.oid from pg_proc p where p.oid=any(array[
   'public.custodial_completion_taxonomy_immutable()'::regprocedure,
   'public.custodial_completion_assert_taxonomy(jsonb)'::regprocedure,
   'public.custodial_completion_taxonomy_response_guard()'::regprocedure,
   'public.custodial_completion_taxonomy_read(text)'::regprocedure,
   'public.custodial_manager_completion_evidence(uuid,text,text)'::regprocedure])
 ),objects as (
  select 100000 bucket,'function'::text kind,oid::regprocedure::text identity,pg_get_functiondef(oid) definition from funcs
  union all select 900000,'grant',oid::regprocedure::text,public.custodial_release_authority_current_grant_definition(oid::regprocedure::text) from funcs
  union all select x.bucket,x.kind,x.identity,x.definition from
   (select 'public.custodial_completion_taxonomy_versions'::text rel) r cross join lateral (
    select 1000 bucket,'relation'::text kind,r.rel identity,public.custodial_release_authority_current_relation_definition(r.rel) definition
    union all select 200000,'column',r.rel||':'||attname,public.custodial_release_authority_current_column_definition(r.rel||':'||attname)
     from pg_attribute where attrelid=r.rel::regclass and attnum>0 and not attisdropped
    union all select 300000,'column_set',r.rel,public.custodial_release_authority_current_column_set_definition(r.rel)
    union all select 400000,'relation_state',r.rel,public.custodial_release_authority_current_relation_state_definition(r.rel)
    union all select 500000,'constraint',r.rel||':'||conname,public.custodial_release_authority_current_constraint_definition(r.rel||':'||conname)
     from pg_constraint where conrelid=r.rel::regclass
    union all select 700000,'trigger',r.rel||'.'||tgname,'drop trigger if exists '||quote_ident(tgname)||' on '||r.rel||'; '
     ||pg_get_triggerdef(oid,true)||'; alter table '||r.rel||case when tgenabled='A' then ' enable always trigger ' else ' enable trigger ' end||quote_ident(tgname)||';'
     from pg_trigger where tgrelid=r.rel::regclass and not tgisinternal
    union all select 900000,'grant',r.rel,public.custodial_release_authority_current_grant_definition(r.rel)
   ) x
  union all select 700000,'trigger','public.completion_responses.'||tgname,
   'drop trigger if exists '||quote_ident(tgname)||' on public.completion_responses; '
   ||pg_get_triggerdef(oid,true)||'; alter table public.completion_responses'
   ||case when tgenabled='A' then ' enable always trigger ' else ' enable trigger ' end||quote_ident(tgname)||';'
   from pg_trigger where tgrelid='public.completion_responses'::regclass and tgname='custodial_completion_taxonomy_response_guard'
 ) select * from objects order by bucket,identity loop
  if obj.definition is null then raise exception 'missing completion taxonomy restore object %',obj.identity;end if;
  update public.custodial_release_authority_restore_inventory set definition_sql=obj.definition,
   definition_sha256=public.static_weekly_digest_text(obj.definition),captured_at=statement_timestamp()
   where object_kind=obj.kind and (object_identity=obj.identity or
    case when obj.kind in ('function','grant') and object_identity like '%(%' and obj.identity like '%(%'
      then to_regprocedure(object_identity)=to_regprocedure(obj.identity) else false end);
  get diagnostics changed=row_count;
  if changed>1 then raise exception 'duplicate completion taxonomy restore object %',obj.identity;end if;
  if changed=0 then
   select n into next_order from generate_series(obj.bucket+1,case when obj.bucket=1000 then 99998 else obj.bucket+99998 end) n
    where not exists(select 1 from public.custodial_release_authority_restore_inventory where restore_order=n) order by n limit 1;
   if next_order is null then raise exception 'completion taxonomy restore order exhausted';end if;
   insert into public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
    values(next_order,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
  end if;
 end loop;
end $recovery$;
alter table public.custodial_release_authority_restore_inventory enable trigger trg_custodial_release_authority_restore_inventory_immutable;

-- No direct table access or newly inherited grants, including after replay.
do $grants$
begin
 if has_table_privilege('anon','public.custodial_completion_taxonomy_versions','SELECT')
  or has_table_privilege('authenticated','public.custodial_completion_taxonomy_versions','SELECT')
  or has_table_privilege('service_role','public.custodial_completion_taxonomy_versions','SELECT')
  or has_function_privilege('anon','public.custodial_manager_completion_evidence(uuid,text,text)','EXECUTE')
  or has_function_privilege('authenticated','public.custodial_manager_completion_evidence(uuid,text,text)','EXECUTE') then
  raise exception 'completion taxonomy least privilege is not in effect';
 end if;
end $grants$;

commit;
